import type { Register } from 'claude-code'

// Runs the mod's own bin/repo-sync quietly every 6 hours. The script writes its result to
// ~/.cache/repo-sync.log; the mod shows nothing.
export const syncCommand = (root: string) => ['bash', `${root}/bin/repo-sync`]

const HOUR = 60 * 60 * 1000
export const PERIOD_MS = 6 * HOUR
export const RUN_TIMEOUT_MS = 10 * 60 * 1000

// The period counts from the last run that worked, so a failed run is tried again at the next hourly check.
// A session claims a run before it starts it; other sessions wait until the claim is older than the longest run.
export const isDue = (lastSuccess: number | null, claimedAt: number | null, now: number) =>
  (lastSuccess === null || now - lastSuccess >= PERIOD_MS) && (claimedAt === null || now - claimedAt >= RUN_TIMEOUT_MS)

// A run that found another sync holding the lock prints "busy:" and did no work.
export const didWork = (exitCode: number, stdout: string) => exitCode === 0 && !stdout.startsWith('busy:')

export const register: Register = on => {
  let isRunning = false

  on('session.start', async ($, e, next) => {
    // A -p run or the SDK may exit in the middle of a run.
    if (!e.isInteractive) return next(e)
    const get = async (key: string) => ((await $.store.get(key)) ?? null) as number | null
    const sync = async () => {
      if (isRunning || !isDue(await get('lastSuccess'), await get('claimedAt'), await $.clock.now())) return
      isRunning = true
      try {
        await $.store.set('claimedAt', await $.clock.now())
        const { exitCode, stdout } = await $.process.run(syncCommand($.plugin.root), { timeoutMs: RUN_TIMEOUT_MS })
        if (didWork(exitCode, stdout)) await $.store.set('lastSuccess', await $.clock.now())
      } finally {
        isRunning = false
      }
    }
    void sync()
    $.clock.every(HOUR, () => void sync())
    return next(e)
  })
}

